type MarketServiceHTTPClient interface {
	// CheckExchange 兑换前置校验
	// 原: PurchaseController::checkExchange -> GoodsLogic::checkExchange
	//     （需要登录；会加 2 秒防重复点击锁并查一次兑换单数量）
	CheckExchange(ctx context.Context, req *CheckExchangeRequest, opts ...http.CallOption) (rsp *CheckExchangeReply, err error)
	// GetGoodsLook 可导入的档案列表（含每个档案的可导入数量）
	//
	// 原实现 PurchaseController::goodsLook -> GoodsLogic::goodsLook($userId, $params)
	// **无校验**（控制器直接 request()->get()）
	//
	//	AppArchive::where(["state"=>1] [+ "id"=>$archive_id])
	//	    ->field("app_id,images as goods_image,name as goods_name,collection_id,id as archive_id")
	//	  + 按 collection_id 分组统计 WarehouseDetail 的可导入数量（num）
	//	缓存：RedisLockService 的 user:stock:goodsLook:{userId}，TTL 5
	//
	// ⚠️ **返回值是顶层数组**（不是 {lists,count,...}）
	// ⚠️ goods_image 的假值分支**保持原值**（不是 []）—— 与 /v1/market/stock/list 不同
	// ⚠️ archive_id 用 isset 语义：传了空串也会当条件（查不到行）
	// 需登录（PurchaseController::$notNeedLogin = ['index']）。
	GetGoodsLook(ctx context.Context, req *GetGoodsLookRequest, opts ...http.CallOption) (rsp *RawData, err error)
	// GetPayWay 支付方式列表
	// 原: PurchaseController::payWay（硬编码，不查库；需要登录）
	GetPayWay(ctx context.Context, req *GetPayWayRequest, opts ...http.CallOption) (rsp *GetPayWayReply, err error)
	// GetSaleCategories 秒转专区分类列表
	// 原: SaleController::categories —— **硬编码**，不查库；是 SaleController 里
	//     唯一免登录的方法（$notNeedLogin = ['categories']）
	GetSaleCategories(ctx context.Context, req *GetSaleCategoriesRequest, opts ...http.CallOption) (rsp *GetSaleCategoriesReply, err error)
	// GetSaleDetail 秒转详情
	//
	// 原实现 SaleController::detail -> SaleLogic::getSaleDetail($id)
	// 校验 SaleDetailValidate: 'id' => 'require|number'
	//
	//	state IN ('ON_SALE','SELL_OUT')   ⚠️ 下架(OFFLINE)查不到
	//	两个 INNER JOIN: app_archive / app，12 列
	//	images 会 json_decode 成数组
	//	返回 {collection, saler, trade_notice}
	//
	// ⚠️ saler 查不到用户时是**空数组 []**（且不补 sale_count 等键）
	// ⚠️ saler.collection_count **恒为 0**（硬编码，不是查出来的）
	// ⚠️ saler.avatar 经 getAvatarAttr 拼域名
	// ⚠️ trade_notice 来自 ConfigService::get('trade','notice')，**无默认值 -> 可能 null**
	// 需登录（SaleController::$notNeedLogin = ['categories']）。
	GetSaleDetail(ctx context.Context, req *GetSaleDetailRequest, opts ...http.CallOption) (rsp *RawData, err error)
	// GetSaleOn 秒转在售藏品（分页）
	//
	// 原实现 SaleController::salesOn -> `$this->dataLists(new SaleOnCollectionLists())`
	// 校验 SaleOnValidate: 'id' => 'require'（'秒转种类ID不能为空'）
	//
	// 构造：findSales(id) 查 archive_id，查不到 **throw new Exception('记录不存在')**
	// where: archive_id = ? AND state = 'ON_SALE'
	// lists: MarketSales JOIN x_app_archive JOIN x_app，7 列，order id desc
	// images 会 json_decode 成数组
	//
	// 🔴 lists 两个 JOIN、count 只有一个 —— 又一处不一致（清单第 3 条）
	GetSaleOn(ctx context.Context, req *GetSaleOnRequest, opts ...http.CallOption) (rsp *RawData, err error)
	// GetSaleOut 秒转已兑出的藏品（分页）
	//
	// 原实现 SaleController::salesOut -> `$this->dataLists(new SaleOutCollectionLists())`
	// 校验 SaleOutValidate: 'id' => 'require'（'秒转种类ID不能为空'）
	//
	// ⚠️⚠️ 与 /v1/market/sales/on **看着对称，实则三处不同**：
	//	查找：`SaleLogic::getArchive($id)`（不是 findSales）—— 查的是 **x_app_archive.id 且 state=1**
	//	错误文案：'存档记录不存在'（不是 '记录不存在'）
	//	状态：SELL_OUT（不是 ON_SALE）
	//	额外字段：每行加 `sale_time_text = ''`（硬编码空串）
	//
	// 其余同 sale/on：7 字段、images json_decode、lists 两个 JOIN / count 一个 JOIN。
	GetSaleOut(ctx context.Context, req *GetSaleOutRequest, opts ...http.CallOption) (rsp *RawData, err error)
	// GetStockList 库存商品明细（分页）
	//
	// 原实现 PurchaseController::stockList -> `$this->dataLists(new StockLists())`
	// **无校验**（控制器没有 goCheck）
	//
	//	where: user_id AND auth_id AND collection_id AND is_locked=1 AND used=0 AND is_use_num=0
	//	collection_id 来自 `AppArchive::where(['id'=>$archive_id])->findOrEmpty()`
	//	**没有 field()** -> SELECT *（x_warehouse_detail 有 24 列）
	//	order: create_time ASC, goods_id ASC   （两个都是升序）
	//	goods_image 逐行 json_decode；空值则赋**空数组 []**
	//
	// ⚠️ archive_id 为空、或档案查不到 -> **空列表 + count=0**（不是报错）
	// ⚠️ auth_id 缺失时**兜底为 0**（不是"不筛"）
	// 需登录（PurchaseController::$notNeedLogin = ['index']）。
	GetStockList(ctx context.Context, req *GetStockListRequest, opts ...http.CallOption) (rsp *RawData, err error)
	// PurchaseIndex 兑换专区首页列表
	// 原: PurchaseController::index -> PurchaseFaceLists
	//     **免登录**（控制器 $notNeedLogin 放行了 index）
	//     挂白名单 no_collection_trade
	//     走交易时段判断；带 20 秒整包缓存
	//
	// 返回 RawData：列表行结构任意（bigint 主键 / decimal 字符串 / json 数组 /
	// "0 转 --" 后处理），用 proto 建模会丢精度又拧巴，见 common.proto 的说明。
	PurchaseIndex(ctx context.Context, req *PurchaseIndexRequest, opts ...http.CallOption) (rsp *RawData, err error)
	// PurchaseInfo 藏品封面（档案基础信息）
	// 原: PurchaseController::purchaseInfo -> MarketListPurchaseLogic::getArchive
	//     **需要登录**；结果按 archive id 缓存 600 秒
	PurchaseInfo(ctx context.Context, req *PurchaseInfoRequest, opts ...http.CallOption) (rsp *PurchaseInfoReply, err error)
	// PurchaseOn 兑换中列表（state=WANTED）
	// 原: PurchaseController::salesOn -> PurchaseStateLists(['state'=>'WANTED'])
	//     需要登录
	//
	// ⚠️ 与 purchase/out 的两处差异：
	//   1. 排序不同：unit_price DESC, grab_time ASC, create_time ASC, id DESC
	//   2. **分页之后**会过滤掉 available_amount <= 0 的行 ——
	//      所以返回行数可能少于 page_size，而 count() 不做这个过滤，
	//      **count 与 lists 天然对不上**（原实现行为，刻意保持）
	//
	// 原实现还挂了 stale-while-revalidate 缓存（逻辑过期 5s / 物理 15s / 重建锁 5s），
	// 本批**未接**，每次直查。功能正确，少了缓存。
	PurchaseOn(ctx context.Context, req *PurchaseOnRequest, opts ...http.CallOption) (rsp *RawData, err error)
	// PurchaseOut 兑换售出列表（state=COMPLETE）
	// 原: PurchaseController::salesOut -> PurchaseStateLists(['state'=>'COMPLETE'])
	//     需要登录；结果按参数 md5 缓存 10 秒（简单 TTL，无锁）
	//
	// ⚠️ count 与 lists 可能对不上：lists 在 SQL 层过滤，但原实现对 WANTED 状态
	//    还有一次**分页之后**的过滤；COMPLETE 分支没有那次过滤。
	PurchaseOut(ctx context.Context, req *PurchaseOutRequest, opts ...http.CallOption) (rsp *RawData, err error)
	// SaleIndex 秒转专区首页列表
	// 原: SaleController::index -> SaleFaceLists
	//     **需要登录**（不在 $notNeedLogin 里）
	//
	// ⚠️ 与 purchase 列表的两个差异（都是实测出来的）：
	//   1. 该接口没有默认排序 —— PurchaseFaceLists 的 switch 有 default 分支，
	//      SaleFaceLists 没有，所以**不带 sort 参数时 SQL 里根本没有 ORDER BY**
	//   2. 行后处理只做 images 的 json 解码，没有 "0 转 --" 那套
	SaleIndex(ctx context.Context, req *SaleIndexRequest, opts ...http.CallOption) (rsp *RawData, err error)
	// SaleInfo 秒转藏品封面
	// 原: SaleController::saleInfo -> MarketListSalesLogic::findSales + SaleLogic::getArchive
	//     **需要登录**
	//
	// ⚠️ 与 PurchaseInfo 不是同一个函数，尽管缓存键看起来一样：
	//    本例走 SaleLogic::getArchive，用 TP 的 cache()（物理键 la:archive:{id}），
	//    **只有 5 个字段**（没有 collection_id / platform_id），TTL 3600s；
	//    PurchaseInfo 走 MarketListPurchaseLogic::getArchive，用 RedisLockService
	//    （物理键 archive:{id}），有 7 个字段，TTL 600s。
	//    两者物理键不同所以不会互相覆盖，但字段集不同 —— 不要"顺手统一"。
	SaleInfo(ctx context.Context, req *SaleInfoRequest, opts ...http.CallOption) (rsp *SaleInfoReply, err error)
	// ShowTotalAmount 计算总额（含服务手续费）
	// 原: PurchaseOrdersController::showTotalAmount -> FeeAmountLogic::showTotalAmount
	//
	// ⚠️ totalAmount 是**字符串**，不是数字：原实现返回的是 bcsub 的结果，
	//    且参数不合法时是 '0'（没有小数位），合法时是 2 位小数。
	ShowTotalAmount(ctx context.Context, req *ShowTotalAmountRequest, opts ...http.CallOption) (rsp *ShowTotalAmountReply, err error)
	// StockLookAll 库存汇总（可释放数量 + 是否有释放任务在处理中）
	// 原: PurchaseController::lookAll -> GoodsLogic::lookAll
	//     **需要登录**；结果缓存 10 秒
	//
	// ⚠️ state 字段迁移期恒为 1：它依赖的"释放任务进行中"标记由 PHP 用
	//    ThinkPHP 的 cache() 写入，键空间与 Go 侧隔离。详见 biz/stock.go。
	StockLookAll(ctx context.Context, req *StockLookAllRequest, opts ...http.CallOption) (rsp *StockLookAllReply, err error)
}

